<template><div class="office-page"><AppSidebar/><main class="main"><header class="head"><div><h2>任务待办</h2><p>行动项、会议邀请、审批流转与逾期提醒</p></div><el-badge :value="unread" :hidden="!unread"><el-button size="small" @click="load">刷新待办</el-button></el-badge></header><el-tabs v-model="tab"><el-tab-pane label="我的待办" name="tasks"><div class="chips"><el-tag type="danger">逾期 {{overdue.length}}</el-tag><el-tag type="warning">待处理 {{tasks.length}}</el-tag><el-tag type="success">已完成 {{done}}</el-tag></div><el-table :data="tasks" size="small" stripe><el-table-column label="任务"><template slot-scope="{row}"><b>{{row.title}}</b><small>{{row.description||'来自会议行动项'}}</small></template></el-table-column><el-table-column label="截止时间" width="170"><template slot-scope="{row}"><el-tag size="mini" :type="isOverdue(row)?'danger':'info'">{{row.start_time}}</el-tag></template></el-table-column><el-table-column label="优先级" width="90"><template slot-scope="{row}"><el-tag size="mini" type="warning">{{row.priority==='high'?'高':row.priority==='low'?'低':'中'}}</el-tag></template></el-table-column><el-table-column label="状态" width="100"><template slot-scope="{row}">{{row.status==='done'?'已完成':'待处理'}}</template></el-table-column></el-table></el-tab-pane><el-tab-pane label="消息提醒" name="notices"><el-card v-for="n in notices" :key="n.id" class="notice" :class="{unread:!n.is_read}" @click.native="read(n)"><div><b>{{n.title}}</b><p>{{n.content}}</p><small>{{n.created_at}}</small></div><el-tag size="mini" :type="n.is_read?'info':'primary'">{{n.is_read?'已读':'未读'}}</el-tag></el-card><el-empty v-if="!notices.length" description="暂无消息"/></el-tab-pane><el-tab-pane label="跨组协同" name="cross"><el-alert title="跨组事项由部门负责人统筹，小组长负责跟进；逾期事项将进入部门风险清单。" type="info" :closable="false"/><el-table :data="tasks" size="small" style="margin-top:12px"><el-table-column prop="title" label="协同事项"/><el-table-column prop="start_time" label="计划节点" width="180"/><el-table-column label="来源" width="120"><template slot-scope="{row}">{{row.meeting_id?'会议行动项':'日程安排'}}</template></el-table-column></el-table></el-tab-pane></el-tabs></main></div></template>
<script>import AppSidebar from '../components/Sidebar/index.vue';export default{components:{AppSidebar},data:()=>({tab:'tasks'}),computed:{ws(){return this.$store.getters['workspace/activeWorkspace']||{}},tasks(){return this.$store.state.office.schedules.filter(x=>x.event_type==='task')},notices(){return this.$store.state.office.notifications},unread(){return this.$store.state.office.unreadNotifications},overdue(){return this.tasks.filter(this.isOverdue)},done(){return this.tasks.filter(x=>x.status==='done').length}},watch:{'ws.id':{immediate:true,handler(){this.load()}}},methods:{load(){if(this.ws.id&&this.ws.domain==='office')return Promise.all([this.$store.dispatch('office/loadSchedules',this.ws.id),this.$store.dispatch('office/loadNotifications',this.ws.id)])},isOverdue(x){return x.status!=='done'&&x.start_time&&new Date(x.start_time)<new Date()},read(n){if(!n.is_read)this.$store.dispatch('office/readNotification',{id:n.id,workspaceId:this.ws.id})}}}</script><style scoped>.office-page{display:flex;min-height:100vh;padding:12px;gap:12px;background:#f3f6fb}.main{flex:1;padding:20px;background:#fff;border-radius:12px}.head{display:flex;justify-content:space-between;align-items:center;padding-bottom:14px;border-bottom:1px solid #edf0f5}.head h2{margin:0 0 5px}.head p,small{color:#8492a6}.chips{margin:8px 0}.chips .el-tag{margin-right:8px}.el-table small{display:block;margin-top:3px}.notice{margin-bottom:8px;cursor:pointer}.notice.unread{border-left:4px solid #409eff}.notice :deep(.el-card__body){display:flex;justify-content:space-between}.notice p{margin:6px 0;color:#627187}.notice small{font-size:12px}</style>
